import{_ as s,a0 as i,w as o,s as b,I as t,x as p,a1 as e,A as u,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const W=JSON.parse('{"title":"Ubuntu 14.04/16.04 與 Windows 10 週年版 Ubuntu Bash 性能對比 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 14.04/16.04 與 Windows 10 週年版 Ubuntu Bash 性能對比 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 14.04/16.04 與 Windows 10 週年版 Ubuntu Bash 性能對比 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 14.04/16.04 與 Windows 10 週年版 Ubuntu Bash 性能對比 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/ubuntu vs ubuntu on windows","title":"Ubuntu 14.04/16.04 與 Windows 10 週年版 Ubuntu Bash 性能對比","tag":"201611","desc":""},"relativePath":"201611/ubuntu vs ubuntu on windows.md","filePath":"[post].md"}'),d={name:"201611/ubuntu vs ubuntu on windows.md"};function r(f,n,l,w,h,g){const a=i("Link");return o(),b("div",null,[n[21]||(n[21]=t("h1",{id:"ubuntu-14-04-16-04-與-windows-10-週年版-ubuntu-bash-性能對比",tabindex:"-1"},[p("Ubuntu 14.04/16.04 與 Windows 10 週年版 Ubuntu Bash 性能對比 "),t("a",{class:"header-anchor",href:"#ubuntu-14-04-16-04-與-windows-10-週年版-ubuntu-bash-性能對比","aria-label":"Permalink to “Ubuntu 14.04/16.04 與 Windows 10 週年版 Ubuntu Bash 性能對比”"},"​")],-1)),t("p",null,[n[2]||(n[2]=p("今年初，當 Microsoft 和 Canonical 發佈 ",-1)),e(a,{href:"http://www.phoronix.com/scan.php?page=news_item&px=Ubuntu-User-Space-On-Win10"},{default:u(()=>[...n[0]||(n[0]=[p("Windows 10 Bash 和 Ubuntu 用户空間",-1)])]),_:1}),n[3]||(n[3]=p("，我嘗試做了一些初步性能測試 ",-1)),e(a,{href:"http://www.phoronix.com/scan.php?page=article&item=windows-10-lxcore&num=1"},{default:u(()=>[...n[1]||(n[1]=[p("Ubuntu on Windows 10 對比 原生 Ubuntu",-1)])]),_:1}),n[4]||(n[4]=p("，這次我發佈更多的，關於原生純淨的 Ubuntu 和基於 Windows 10 的基準對比。",-1))]),n[22]||(n[22]=t("p",null,[t("img",{src:"http://www.phoronix.net/image.php?id=windows10-anv-wsl&image=windows_wsl_1_med",alt:"Windows 的 Linux 子系統"})],-1)),n[23]||(n[23]=t("p",null,"Windows 的 Linux 子系統測試完成了所有測試，並隨着 Windows 10週年更新放出。 默認的 Ubuntu 用户空間還是 Ubuntu 14.04，但是已經可以升級到 16.04。所以測試首先在 14.04 測試，完成後將系統升級升級到 16.04 版本並重復所有測試。完成所有基於 Windows 的 Ubuntu 子系統測試後，我在同樣的系統上乾淨地安裝了 Ubuntu 14.04.5 和 Ubuntu 16.04 LTS 來做性能對比。",-1)),n[24]||(n[24]=t("p",null,[t("img",{src:"http://www.phoronix.net/image.php?id=windows10-anv-wsl&image=windows_wsl_2_med",alt:"Ubuntu"})],-1)),n[25]||(n[25]=t("p",null,"配置為 Intel i5 6600K Skylake，16G 內存和 256G 東芝 ssd，測試過程中每個操作系統都採用其原生默認配置和軟件包。",-1)),n[26]||(n[26]=t("p",null,[t("img",{src:"https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&sha=09989b3&p=2",alt:"Phoronix 測試套件"})],-1)),t("p",null,[n[6]||(n[6]=p("這次 Ubuntu/Bash on Windows 和原生 Ubuntu 對比測試，採用開源軟件 ",-1)),e(a,{href:"http://www.phoronix-test-suite.com/"},{default:u(()=>[...n[5]||(n[5]=[p("Phoronix 測試套件",-1)])]),_:1}),n[7]||(n[7]=p("，完全自動化並可重複測試。",-1))]),n[27]||(n[27]=m('<p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=186c4d0&amp;c=a8c914bf9b64cf67abc65e319f8e71c7951fb1aa&amp;p=0" alt="SQLite 嵌入式資料庫基準測試"></p><p>首先是 SQLite 嵌入式資料庫基準測試。這方面開箱即用的 Ubuntu/Bash on Windows 性能是相當的慢，但是如果將環境從 14.04 升級到 16.04 LTS，性能會快很多。然而，對於繁重磁盤操作的任務，原生 Ubuntu Linux 幾乎比 Windows 的子系統 Linux 快了近 2 倍。</p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=fa40825&amp;c=0912dc3f6d6a9f36da09fdd4c0cf4e330fa40f90&amp;p=0" alt="編譯測試：編譯"></p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=8419652&amp;c=9b9f6b0822ed5b9dc2977a7f2faf499fce4fba23&amp;p=0" alt="編譯測試：初始創建"></p><p>編譯測試作為額外的繁重磁盤操作測試顯示，定製的 Windows 子系統真的成倍的限制了 Ubuntu 性能。</p><p>接下來，是一些使用 Stream 的基本的系統內存速度測試：</p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=9560e6f&amp;c=ebbc6937fa8daf0540e0df353432a29f938cf7ed&amp;p=0" alt="Stream：複製"></p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=63fa8d6&amp;c=88cd58f9eca6d3a09699d60d9f877529113fb1bc&amp;p=0" alt="Stream：縮放"></p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=5a2e9d2&amp;c=d37eee4c9394fa8104e7e49e26c964af70ec326b&amp;p=0" alt="Stream：添加"></p><p>奇怪的是，這些 Stream 內存的基準測試顯示 Ubuntu on Windows 的性能比原生的 Ubuntu 好！這個現象同時發生在基於同樣的 Windows 卻環境不同的 14.04 和 16.04 LTS 上。</p><p>接下來，是一些繁重 CPU 操作測試。</p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=ee1f01f&amp;c=3e9a67230e0e081b99ee3237e702c0b40ee73d60&amp;p=0" alt="Dolfyn 科學測試"></p><p>通過 Dolfyn 科學測試，Ubuntu On Windows 和原生 Ubuntu 之間的性能其實是相當接近的。 對於 Ubuntu 16.04，由於較新的 GCC 編譯器性能衰減，兩個平台上的性能都較慢。</p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=dd69257&amp;c=0e31babb8b96be1ae38ea739fbb1346bf9bc4b07&amp;p=0" alt="Fhourstones 測試"></p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=a02416b&amp;c=c8abb70dee982dd494fb1891bd9dc154fa7a7f47&amp;p=0" alt="John The Ripper 測試"></p><p>透過 Fhourstones 測試和 John The Ripper 測試表明，通過在 Windows 的 Linux 子系統運行的 Ubuntu 的性能可以非常接近裸機 Ubuntu Linux 性能！</p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=3140e3c&amp;c=f4bf6330a7d58b5939c61cbd91fe5db379c1592a&amp;p=0" alt="x264 測試：H264視頻編碼"></p><p>類似於 Stream 測試，x264 結果是另一個奇怪的情況，其中最好的性能實際上是使用 Linux 子系統的 Ubuntu On Windows！</p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=ad12f0b&amp;c=f50c829c97d731f6926c5a874cf83f8fc5440067&amp;p=0" alt="Linux 內核編譯時間"></p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=8b7a7ca&amp;c=3de3e8537d08665e8a41380b6b2298c09f408fa0&amp;p=0" alt="PHP 編譯時間"></p><p>計時編譯基準測試非常利於裸機 Ubuntu Linux。這是應該是由於大型程序編譯需要大量讀寫磁盤，在先前測試已經發現了，這是基於 Windows 的 Linux 子系統緩慢的一大領域。</p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=25892d8&amp;c=f6cd3fa4a3497e3d2663106e0bf3fcd227f9b9a3&amp;p=0" alt="Crafty"></p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=2ea1062&amp;c=fbbec58a6aa1f3fb8dbc55e3de612afc99c666f7&amp;p=0" alt="FLAC 音頻編碼"></p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=4899bb2&amp;c=80df0e1e749910ebd84b0d6c2688316e5cfb8cda&amp;p=0" alt="OpenSSL"></p><p>許多其他的通用開源基準測試表明，嚴格的針對 CPU 的測試，Windows 子系統的 Ubuntu 的性能是很接近的，甚至是與原生安裝在實際硬件中的 Ubuntu Linux 相等。</p><p>最新的 Windows 的 Linux 子系統，測試結果實際上相當令人印象深刻。讓人沮喪的僅僅只是持續緩慢的磁盤/文件系統性能，但是對於受 CPU 限制的工作負載，結果是非常引人注目的。還有很罕見的情況， x264 和 Stream 測試，Ubuntu On Windows 上的性能看起來明顯優於運行在實際硬件上 的Ubuntu Linux。</p><p>總的來説，體驗是十分愉快的，並且在 Ubuntu/Bash on Windows 也沒有遇到任何其他的 bug。如果你有還興趣瞭解更多關於 Windows 和 Linux 的基準測試，歡迎留言討論。</p><hr>',28)),t("p",null,[n[9]||(n[9]=p("via: ",-1)),e(a,{href:"https://www.phoronix.com/scan.php?page=article&item=windows10-anv-wsl&num=1"},{default:u(()=>[...n[8]||(n[8]=[p("https://www.phoronix.com/scan.php?page=article&item=windows10-anv-wsl&num=1",-1)])]),_:1})]),t("p",null,[n[13]||(n[13]=p("作者：",-1)),e(a,{href:"http://www.michaellarabel.com/"},{default:u(()=>[...n[10]||(n[10]=[p("Michael Larabel",-1)])]),_:1}),n[14]||(n[14]=p(" 譯者：",-1)),e(a,{href:"http://vicyu.net"},{default:u(()=>[...n[11]||(n[11]=[p("VicYu/Vic020",-1)])]),_:1}),n[15]||(n[15]=p(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:u(()=>[...n[12]||(n[12]=[p("wxy",-1)])]),_:1})]),t("p",null,[n[18]||(n[18]=p("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...n[16]||(n[16]=[p("LCTT",-1)])]),_:1}),n[19]||(n[19]=p(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:u(()=>[...n[17]||(n[17]=[p("Linux中國",-1)])]),_:1}),n[20]||(n[20]=p(" 榮譽推出",-1))])])}const x=s(d,[["render",r]]);export{W as __pageData,x as default};
